// ─────────────────────────────────────────────────────────────────────────────
// Shared database types for the Learning App
// Generated by hand from supabase/migrations schema; keep in sync with SQL.
// ─────────────────────────────────────────────────────────────────────────────

export type QuestionStatus = 'draft' | 'reviewed' | 'approved' | 'live' | 'quarantined';
export type UserRole = 'student' | 'reviewer' | 'admin';
export type ReportReason = 'wrong_answer' | 'unclear' | 'typo' | 'other';
export type OptionKey = 'A' | 'B' | 'C' | 'D';
export type DifficultyLevel = 1 | 2 | 3;
export type ClassLevel = 5 | 6 | 7 | 8 | 9 | 10;

// ── Syllabus ──────────────────────────────────────────────────────────────────

export interface Subject {
  id: string;
  name: string;
}

export interface Chapter {
  id: string;
  class_level: ClassLevel;
  subject_id: string;
  number: number;
  title: string;
}

export interface Topic {
  id: string;
  chapter_id: string;
  title: string;
  learning_outcome: string | null;
}

export interface TopicPrerequisite {
  topic_id: string;
  requires_topic_id: string;
}

// ── Content ───────────────────────────────────────────────────────────────────

export interface Misconception {
  id: string;
  topic_id: string;
  description: string;
  remediation_note: string | null;
}

export interface QuestionFamily {
  id: string;
  topic_id: string;
  description: string | null;
}

export type BodyFormat = 'plain' | 'latex';

export interface Question {
  id: string;
  family_id: string;
  chapter_id: string;
  topic_id: string;
  difficulty: DifficultyLevel;
  body_format: BodyFormat;
  body: string;
  explanation: string;
  status: QuestionStatus;
  source: string;
  reviewed_by: string | null;
  version: number;
  created_at: string;
  updated_at: string;
}

export interface QuestionOption {
  id: string;
  question_id: string;
  option_key: OptionKey;
  text: string;
  is_correct: boolean;
  misconception_id: string | null;
  is_random_distractor: boolean;
}

// ── Users & learning state ────────────────────────────────────────────────────

export interface Profile {
  id: string;
  nickname: string | null;
  class_level: ClassLevel | null;
  parent_contact: string | null;
  consent_recorded_at: string | null;
  xp: number;
  streak_days: number;
  last_active_date: string | null;
  role: UserRole;
}

export interface Session {
  id: string;
  user_id: string;
  chapter_id: string | null;
  started_at: string;
  ended_at: string | null;
}

export interface Attempt {
  id: string;
  user_id: string;
  question_id: string;
  session_id: string | null;
  chosen_option: OptionKey;
  is_correct: boolean;
  time_ms: number | null;
  answered_at: string;
}

export interface Mastery {
  user_id: string;
  chapter_id: string;
  level: DifficultyLevel;
  score: number;
  correct_streak: number;
  wrong_streak: number;
}

export interface StudentMisconception {
  user_id: string;
  misconception_id: string;
  hit_count: number;
  success_count: number;
  last_hit_at: string | null;
  resolved: boolean;
}

export interface ReviewQueue {
  user_id: string;
  question_id: string;
  due_at: string;
  stage: number;
}

export interface QuestionReport {
  id: string;
  question_id: string;
  user_id: string | null;
  reason: ReportReason;
  note: string | null;
  created_at: string;
  resolved: boolean;
}

// ── Question stats view ───────────────────────────────────────────────────────

export interface QuestionStats {
  question_id: string;
  total_attempts: number;
  accuracy: number; // 0–1
  pick_rate_a: number;
  pick_rate_b: number;
  pick_rate_c: number;
  pick_rate_d: number;
  median_time_ms: number | null;
}

// ── Selector types (used by /packages/selector) ───────────────────────────────

export interface SelectorInput {
  userId: string;
  chapterId: string | null;
  currentLevel: DifficultyLevel;
  seenQuestionIds: Set<string>;
  dueReviewIds: string[];
  activeMisconceptionIds: string[];
  recentFamilyIds: string[]; // last 5 questions
}

export type SelectorSignal = 'chapter_complete' | 'concept_note';

export interface SelectorOutput {
  questionIds: string[];
  signal?: SelectorSignal;
  conceptNote?: string; // topic.learning_outcome when stuck
}

// ── Remote config (migration 0009) ────────────────────────────────────────────

export interface RemoteConfig {
  key: string;
  value: string;
  description: string | null;
  updated_at: string;
}

// Well-known remote config keys (not exhaustive — admin can add more)
export type RemoteConfigKey = 'APP_MIN_VERSION' | 'VALIDATE_ON_SERVER' | 'GUEST_DAILY_LIMIT';

// ── Analytics events (migration 0008 — M6) ────────────────────────────────────

export type AnalyticsEventName =
  | 'session_started'
  | 'question_served'
  | 'question_answered'
  | 'level_changed'
  | 'misconception_hit'
  | 'misconception_resolved'
  | 'chapter_complete'
  | 'question_reported'
  | 'session_ended'
  | 'streak_extended';

export interface AnalyticsEvent {
  id: string;
  user_id: string | null;
  session_id: string | null;
  event_name: AnalyticsEventName;
  props: Record<string, unknown>; // MUST NOT contain PII
  client_ts: string;
  server_ts: string;
}
